import Link from "next/link";
import { cn, isExternal } from "@/lib/utils";

type Variant = "dark" | "outline" | "outline-light" | "light";
type Size = "md" | "lg";

const base =
  "btn inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-[var(--radius-btn)] border font-medium transition-[background-color,color,border-color,scale,opacity] duration-300 ease-out active:scale-[0.97]";

const variants: Record<Variant, string> = {
  dark: "btn-ring [--btn-fill:var(--color-ink)] text-on-ink hover:opacity-85",
  outline: "border-ink bg-transparent text-ink hover:bg-ink hover:text-on-ink",
  "outline-light": "border-white/90 bg-transparent text-white hover:bg-white hover:text-coal hover:border-white",
  light: "btn-ring theme-light [--btn-fill:var(--color-band)] text-ink hover:[--btn-fill:#fff]",
};

const sizes: Record<Size, string> = {
  md: "h-[clamp(42px,calc(0.65vw+39.5px),52px)] px-[clamp(16px,calc(0.52vw+14px),24px)] text-base",
  lg: "h-[clamp(52px,calc(2.23vw+43.6px),86px)] px-[clamp(22px,calc(1.5vw+16.4px),45px)] text-[length:clamp(17px,calc(0.59vw+14.8px),26px)] font-normal",
};

export function buttonClass(variant: Variant = "dark", size: Size = "md", className?: string) {
  return cn(base, variants[variant], sizes[size], className);
}

type Props = {
  href: string;
  children: React.ReactNode;
  variant?: Variant;
  size?: Size;
  className?: string;
};

export function ButtonLink({ href, children, variant = "dark", size = "md", className }: Props) {
  const cls = buttonClass(variant, size, className);
  const label = <span className="btn-label">{children}</span>;
  if (isExternal(href)) {
    return (
      <a href={href} className={cls} target="_blank" rel="noopener noreferrer">
        {label}
      </a>
    );
  }
  return (
    <Link href={href} className={cls}>
      {label}
    </Link>
  );
}
